BEGIN;
SET LOCAL statement_timeout='30s';
SET LOCAL lock_timeout='5s';
DO $$
DECLARE l campaign_lines%ROWTYPE; a campaign_influencers%ROWTYPE; d assignment_deliverables%ROWTYPE;
 actor uuid; invoice_key uuid; invoice_before jsonb; child_before jsonb; base_revenue numeric; blocked boolean;
BEGIN
 SELECT * INTO STRICT l FROM campaign_lines WHERE NOT cost_locked AND vendor_io_id IS NULL AND EXISTS(SELECT 1 FROM campaign_influencers WHERE campaign_line_id=campaign_lines.id) AND EXISTS(SELECT 1 FROM assignment_deliverables WHERE campaign_line_id=campaign_lines.id) LIMIT 1;
 SELECT * INTO STRICT a FROM campaign_influencers WHERE campaign_line_id=l.id LIMIT 1;
 SELECT * INTO STRICT d FROM assignment_deliverables WHERE campaign_line_id=l.id LIMIT 1;
 SELECT created_by INTO actor FROM campaign_headers WHERE id=l.campaign_header_id;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 l:=jsonb_populate_record(l,jsonb_build_object('id',gen_random_uuid(),'document_number','QA-APPROVED-COST','name','QA cost flow','invoice_id',NULL,'vendor_io_id',NULL,'cost_locked',false,'revenue_locked',false,'vat_locked',false,'vendor_assignment_locked',false,'cost',100000,'cost_before_vat',100000,'cost_received',100000,'cost_received_currency','EGP','currency_code','EGP','cost_vat_percent',0,'cost_vat_exempt',true,'fx_rate',1,'fx_cost_revenue_cross_rate',NULL,'pricing_mode','package','metadata','{}'::jsonb));
 INSERT INTO campaign_lines SELECT l.*;
 a:=jsonb_populate_record(a,jsonb_build_object('id',gen_random_uuid(),'campaign_line_id',l.id,'agreed_fee',100000,'cost_before_vat',100000,'cost_after_vat',100000,'vendor_payment_status','unpaid'));
 INSERT INTO campaign_influencers SELECT a.*;
 INSERT INTO creator_payment_terms(assignment_id,campaign_id,fee,vat,updated_by) VALUES(a.id,l.campaign_header_id,100000,0,actor);
 d:=jsonb_populate_record(d,jsonb_build_object('id',gen_random_uuid(),'campaign_line_id',l.id,'quantity',1,'unit_cost',25000,'total_cost',25000,'cost_before_vat',25000,'locked_at',NULL));
 INSERT INTO assignment_deliverables SELECT d.*;
 d.id:=gen_random_uuid(); INSERT INTO assignment_deliverables SELECT d.*;
 d.id:=gen_random_uuid(); INSERT INTO assignment_deliverables SELECT d.*;
 d.id:=gen_random_uuid(); INSERT INTO assignment_deliverables SELECT d.*;
 SELECT id,to_jsonb(i) INTO invoice_key,invoice_before FROM invoices i WHERE issue_date IS NOT NULL LIMIT 1;
 UPDATE campaign_lines SET invoice_id=invoice_key,vat_locked=true,revenue_locked=true WHERE id=l.id;
 SELECT revenue_before_vat INTO base_revenue FROM campaign_lines WHERE id=l.id;
 SELECT jsonb_agg(to_jsonb(x)-ARRAY['cost_before_vat','total_cost','unit_cost','usage_rights_cost','cost_vat_percent','cost_vat_exempt','cost_vat_amount','cost_after_vat','updated_at'] ORDER BY id) INTO child_before FROM assignment_deliverables x WHERE campaign_line_id=l.id;
 PERFORM apply_assignment_commercial_cost(l.id,'{"cost_before_vat":70000}');
 IF NOT EXISTS(SELECT 1 FROM campaign_lines WHERE id=l.id AND cost=70000 AND cost_before_vat=70000 AND cost_received=70000 AND revenue_before_vat=base_revenue) THEN RAISE EXCEPTION 'Master/native cost incorrect'; END IF;
 IF NOT EXISTS(SELECT 1 FROM campaign_influencers WHERE id=a.id AND agreed_fee=70000 AND cost_before_vat=70000 AND cost_after_vat=70000) THEN RAISE EXCEPTION 'Creator payable stale'; END IF;
 IF (SELECT fee FROM creator_payment_terms WHERE assignment_id=a.id)<>70000 THEN RAISE EXCEPTION 'Payment terms stale'; END IF;
 IF (SELECT sum(cost_before_vat) FROM assignment_deliverables WHERE campaign_line_id=l.id)<>70000 OR EXISTS(SELECT 1 FROM assignment_deliverables WHERE campaign_line_id=l.id AND unit_cost<>17500) THEN RAISE EXCEPTION 'Children stale'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x)-ARRAY['cost_before_vat','total_cost','unit_cost','usage_rights_cost','cost_vat_percent','cost_vat_exempt','cost_vat_amount','cost_after_vat','updated_at'] ORDER BY id) FROM assignment_deliverables x WHERE campaign_line_id=l.id) IS DISTINCT FROM child_before THEN RAISE EXCEPTION 'Child revenue, IDs or operational data changed'; END IF;
 IF (SELECT to_jsonb(i) FROM invoices i WHERE id=invoice_key) IS DISTINCT FROM invoice_before THEN RAISE EXCEPTION 'Client invoice changed'; END IF;
 blocked:=false;
 BEGIN PERFORM apply_assignment_commercial_cost(l.id,jsonb_build_object('cost_before_vat',60000,'revenue_before_vat',base_revenue+100)); EXCEPTION WHEN check_violation THEN blocked:=true; END;
 IF NOT blocked OR (SELECT cost_received FROM campaign_lines WHERE id=l.id)<>70000 THEN RAISE EXCEPTION 'Client lock or rollback failed'; END IF;
 -- Foreign native amount follows the stored conversion, not a same-currency assumption.
 UPDATE campaign_lines SET cost_received_currency='USD',cost_received=1400,fx_cost_revenue_cross_rate=50 WHERE id=l.id;
 PERFORM apply_assignment_commercial_cost(l.id,'{"cost_before_vat":50000}');
 IF (SELECT cost_received FROM campaign_lines WHERE id=l.id)<>1000 OR (SELECT fee FROM creator_payment_terms WHERE assignment_id=a.id)<>50000 THEN RAISE EXCEPTION 'Foreign cost conversion failed'; END IF;
 UPDATE campaign_lines SET metadata=metadata || '{"vendor_native_cost":true}'::jsonb WHERE id=l.id;
 PERFORM apply_assignment_commercial_cost(l.id,'{"cost_before_vat":50000}');
 IF (SELECT fee FROM creator_payment_terms WHERE assignment_id=a.id)<>1000 THEN RAISE EXCEPTION 'Native vendor payable wrong'; END IF;
 UPDATE campaign_influencers SET vendor_payment_status='paid'  WHERE id=a.id;
 blocked:=false;
 BEGIN PERFORM apply_assignment_commercial_cost(l.id,'{"cost_before_vat":40000}'); EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked OR (SELECT cost_before_vat FROM campaign_lines WHERE id=l.id)<>50000 THEN RAISE EXCEPTION 'Payment guard failed'; END IF;
 RAISE NOTICE 'PASS: approved cost -> native display -> creator payable -> terms -> four child rows; client invoice and child revenue preserved; rollback, FX and paid locks verified';
END $$;
ROLLBACK;
